export default function AlertPanel({ alerts = [] }) {
  if (!alerts.length) return null;

  return (
    <div style={{
      background: 'var(--bg-card)',
      border: '1px solid var(--border)',
      borderRadius: 'var(--radius-lg)',
      overflow: 'hidden',
      animation: 'fadeUp 0.5s ease 0.3s both',
    }}>
      <div style={{
        padding: '14px 20px',
        borderBottom: '1px solid var(--border)',
        display: 'flex', alignItems: 'center', gap: 8,
      }}>
        <div style={{
          width: 8, height: 8, borderRadius: '50%',
          background: 'var(--red)',
          animation: 'pulse-gold 1.5s ease infinite',
        }}/>
        <span style={{
          fontFamily: 'var(--font-mono)', fontSize: 11,
          color: 'var(--text-secondary)', letterSpacing: '0.1em',
          textTransform: 'uppercase',
        }}>
          Market alerts — {alerts.length} active
        </span>
      </div>

      {alerts.map((a, i) => (
        <div key={i} style={{
          padding: '16px 20px',
          borderBottom: i < alerts.length - 1 ? '1px solid var(--border)' : 'none',
          display: 'flex', gap: 14, alignItems: 'flex-start',
          transition: 'background 0.15s',
        }}
        onMouseEnter={e => e.currentTarget.style.background = 'var(--bg-card-hover)'}
        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
        >
          <div style={{
            width: 28, height: 28, borderRadius: 8, flexShrink: 0,
            background: a.severity === 'danger' ? 'var(--red-dim)' : 'rgba(240,180,41,0.1)',
            border: `1px solid ${a.severity === 'danger' ? 'var(--red)' : 'var(--gold)'}30`,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 13,
          }}>
            {a.severity === 'danger' ? '⚠' : '↘'}
          </div>

          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{
              fontFamily: 'var(--font-display)', fontWeight: 600, fontSize: 13,
              color: a.severity === 'danger' ? 'var(--red)' : 'var(--gold)',
              marginBottom: 4,
            }}>
              {a.headline}
            </div>
            <div style={{ fontSize: 12, color: 'var(--text-secondary)', lineHeight: 1.5, marginBottom: 6 }}>
              {a.detail}
            </div>
            <div style={{
              fontFamily: 'var(--font-mono)', fontSize: 11,
              color: a.severity === 'danger' ? 'var(--red)' : 'var(--gold)',
              background: a.severity === 'danger' ? 'var(--red-dim)' : 'var(--gold-dim)',
              display: 'inline-block', padding: '3px 8px',
              borderRadius: 4,
            }}>
              {a.cost_impact}
            </div>
            <div style={{ marginTop: 6, fontSize: 11, color: 'var(--text-dim)', fontStyle: 'italic' }}>
              → {a.action_prompt}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
